/// Returns 1.0 if i == j, otherwise returns 0.0.
fn diag_val(i: usize, j: usize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

/// Constructs an n×n identity matrix of f64 values.
fn identity(n: usize) -> Vec<Vec<f64>> {
    // For each row index `i`, build a row by mapping each column index `j`
    // through `diag_val(i, j)`, then collect into a Vec<f64>.
    (0..n)
        .map(|i| {
            (0..n)
                .map(|j| diag_val(i, j))
                .collect::<Vec<f64>>()
        })
        .collect::<Vec<Vec<f64>>>()
}

fn main() {
    // Example usage:
    let mat = identity(4);
    for row in &mat {
        println!("{:?}", row);
    }
}